import{_ as t,o as e,c as o,a2 as r}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"WeChat（個人アカウント）","description":"","frontmatter":{},"headers":[],"relativePath":"ja/integrations/channels/weixin.md","filePath":"ja/integrations/channels/weixin.md","lastUpdated":1792323081000}'),i={name:"ja/integrations/channels/weixin.md"};function h(n,a,l,s,d,c){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="wechat-個人アカウント" tabindex="-1">WeChat（個人アカウント） <a class="header-anchor" href="#wechat-個人アカウント" aria-label="Permalink to &quot;WeChat（個人アカウント）&quot;">​</a></h1><p>Memoh Bot を個人の WeChat につなぎます。QR コードをスキャンするだけでログインでき、token や API key を手入力する必要はありません。</p><div class="warning custom-block"><p class="custom-block-title">使用制限</p><ul><li>プライベートチャットのみ対応します。</li><li>出力はプレーンテキストのみで、Markdown はレンダリングされません。</li><li>テキストメッセージは 1 通あたり最大 4000 文字に分割して送信されます。</li><li>返信は完全なメッセージ単位で届き、ストリーミング出力はありません。</li></ul></div><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ul><li>スマートフォンに WeChat がインストールされ、Bot に使うアカウントでログインしていること。ログインはスマートフォンでの QR コードスキャンで確認します。</li></ul><h2 id="手順" tabindex="-1">手順 <a class="header-anchor" href="#手順" aria-label="Permalink to &quot;手順&quot;">​</a></h2><h3 id="_1-memoh-で-wechat-チャネルを追加する" tabindex="-1">1. Memoh で WeChat チャネルを追加する <a class="header-anchor" href="#_1-memoh-で-wechat-チャネルを追加する" aria-label="Permalink to &quot;1. Memoh で WeChat チャネルを追加する&quot;">​</a></h3><p>Memoh で Bot の <strong>プラットフォーム</strong> タブを開き、<strong>Add Channel</strong> をクリックして <strong>WeChat</strong> を選択します。</p><h3 id="_2-qr-コードでログインする" tabindex="-1">2. QR コードでログインする <a class="header-anchor" href="#_2-qr-コードでログインする" aria-label="Permalink to &quot;2. QR コードでログインする&quot;">​</a></h3><p>Memoh で次を行います。</p><ol><li><strong>Start QR Login</strong> をクリックします。Memoh が WeChat プラットフォームから QR コードを取得します。</li><li>スマートフォンの WeChat で、画面に表示された QR コードをスキャンします。</li><li>スマートフォンでログインを確認します。</li></ol><p>確認が済むと、Memoh が認証情報を自動的に保存し、チャネルはすぐに有効になります。</p><h2 id="認証情報" tabindex="-1">認証情報 <a class="header-anchor" href="#認証情報" aria-label="Permalink to &quot;認証情報&quot;">​</a></h2><p>QR コードでログインすると、セッションの認証情報は Memoh が自動的に保存するため、手入力するフィールドはありません。オプション設定が 1 つあります。</p><table tabindex="0"><thead><tr><th>フィールド</th><th>必須</th><th>説明</th></tr></thead><tbody><tr><td><strong>Enable Typing</strong></td><td>いいえ</td><td>返信の生成中に「入力中」のステータスを表示します。</td></tr></tbody></table><h2 id="動作確認" tabindex="-1">動作確認 <a class="header-anchor" href="#動作確認" aria-label="Permalink to &quot;動作確認&quot;">​</a></h2><p>QR コードのログインが成功すると、チャネルは自動的に有効になります。WeChat のプライベートチャットで Bot に <code>/help</code> を送り、Bot がコマンド一覧を返せば、チャネルは接続できています。</p><h2 id="無効化と認証情報の更新" tabindex="-1">無効化と認証情報の更新 <a class="header-anchor" href="#無効化と認証情報の更新" aria-label="Permalink to &quot;無効化と認証情報の更新&quot;">​</a></h2><p>Bot の <strong>プラットフォーム</strong> タブから、いつでもこのチャネルを無効化・削除できます。再ログインが必要なときは、もう一度 <strong>Start QR Login</strong> をクリックして QR コードの手順をやり直してください。</p><h2 id="faq" tabindex="-1">よくある質問 <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;よくある質問 {#faq}&quot;">​</a></h2><h3 id="qr-expired" tabindex="-1">スキャンする前に QR コードの有効期限が切れた <a class="header-anchor" href="#qr-expired" aria-label="Permalink to &quot;スキャンする前に QR コードの有効期限が切れた {#qr-expired}&quot;">​</a></h3><p>QR コードには有効期限があります。<strong>Start QR Login</strong> をもう一度クリックして、新しい QR コードを取得してください。</p>',22)])])}const u=t(i,[["render",h]]);export{m as __pageData,u as default};
